"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[4121],{33860(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>s,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"cursos/cleancode/modulos/introduccion-clean-code/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 plantea el movimiento \\"Software Craftsmanship\\" iniciado por Pete McBreen, y qu\xe9 cr\xedticas ha recibido desde ciertos sectores del desarrollo \xe1gil?","source":"@site/docs/cursos/cleancode/modulos/01-introduccion-clean-code/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/01-introduccion-clean-code","slug":"/cursos/cleancode/modulos/introduccion-clean-code/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/introduccion-clean-code/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/introduccion-clean-code/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/introduccion-clean-code/ejercicio"}}');var n=o(74848),r=o(28453);const s={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 plantea el movimiento &quot;Software Craftsmanship&quot; iniciado por Pete McBreen, y qu\xe9 cr\xedticas ha recibido desde ciertos sectores del desarrollo \xe1gil?",id:"2-investigar-qu\xe9-plantea-el-movimiento-software-craftsmanship-iniciado-por-pete-mcbreen-y-qu\xe9-cr\xedticas-ha-recibido-desde-ciertos-sectores-del-desarrollo-\xe1gil",level:3},{value:"3. [Investigar] \xbfQu\xe9 es la &quot;Complexity Theory of Technical Debt&quot; de Steve McConnell y c\xf3mo clasifica \xe9l la deuda t\xe9cnica de manera diferente a Fowler?",id:"3-investigar-qu\xe9-es-la-complexity-theory-of-technical-debt-de-steve-mcconnell-y-c\xf3mo-clasifica-\xe9l-la-deuda-t\xe9cnica-de-manera-diferente-a-fowler",level:3},{value:"4. [Investigar] \xbfQu\xe9 revel\xf3 el estudio &quot;The Impact of Technical Debt on Developer Productivity&quot; (Stol et al., 2019) sobre las m\xe9tricas reales de cu\xe1nto tiempo pierden los desarrolladores por deuda t\xe9cnica?",id:"4-investigar-qu\xe9-revel\xf3-el-estudio-the-impact-of-technical-debt-on-developer-productivity-stol-et-al-2019-sobre-las-m\xe9tricas-reales-de-cu\xe1nto-tiempo-pierden-los-desarrolladores-por-deuda-t\xe9cnica",level:3},{value:"5. [Conectar] La clase menciona la &quot;Broken Window Theory&quot; originada en criminolog\xeda por Wilson y Kelling. \xbfC\xf3mo fue espec\xedficamente testeada esta teor\xeda en software por Nachiappan Nagappan (Microsoft Research), y qu\xe9 resultados cuantitativos obtuvo?",id:"5-conectar-la-clase-menciona-la-broken-window-theory-originada-en-criminolog\xeda-por-wilson-y-kelling-c\xf3mo-fue-espec\xedficamente-testeada-esta-teor\xeda-en-software-por-nachiappan-nagappan-microsoft-research-y-qu\xe9-resultados-cuantitativos-obtuvo",level:3},{value:"6. [Conectar] La clase presenta las 4 reglas de dise\xf1o simple de Kent Beck. \xbfC\xf3mo se relacionan estas 4 reglas con el concepto de &quot;Ease&quot; vs &quot;Simplicity&quot; que Rich Hickey (creador de Clojure) desarroll\xf3 en su charla &quot;Simple Made Easy&quot;?",id:"6-conectar-la-clase-presenta-las-4-reglas-de-dise\xf1o-simple-de-kent-beck-c\xf3mo-se-relacionan-estas-4-reglas-con-el-concepto-de-ease-vs-simplicity-que-rich-hickey-creador-de-clojure-desarroll\xf3-en-su-charla-simple-made-easy",level:3},{value:"7. [Conectar] La clase menciona que &quot;el 70-90% del tiempo de un desarrollador es leyendo c\xf3digo&quot; citando a Robert C. Martin. \xbfQu\xe9 metodolog\xeda espec\xedfica us\xf3 el estudio &quot;Developer Reading Behavior&quot; (Buse &amp; Weimer, 2012) para medir la legibilidad de c\xf3digo, y qu\xe9 factores resultaron M\xc1S predictivos de legibilidad que la complejidad ciclom\xe1tica?",id:"7-conectar-la-clase-menciona-que-el-70-90-del-tiempo-de-un-desarrollador-es-leyendo-c\xf3digo-citando-a-robert-c-martin-qu\xe9-metodolog\xeda-espec\xedfica-us\xf3-el-estudio-developer-reading-behavior-buse--weimer-2012-para-medir-la-legibilidad-de-c\xf3digo-y-qu\xe9-factores-resultaron-m\xe1s-predictivos-de-legibilidad-que-la-complejidad-ciclom\xe1tica",level:3},{value:"8. [Cuestionar] La &quot;Boy Scout Rule&quot; de Robert C. Martin promueve peque\xf1as refactorizaciones en cada commit. \xbfQu\xe9 objeciones plantean autores como Yegor Bugayenko (autor de &quot;Elegant Objects&quot;) o John Ousterhout (&quot;A Philosophy of Software Design&quot;) a este enfoque incremental? \xbfEn qu\xe9 contexto la regla podr\xeda ser contraproducente?",id:"8-cuestionar-la-boy-scout-rule-de-robert-c-martin-promueve-peque\xf1as-refactorizaciones-en-cada-commit-qu\xe9-objeciones-plantean-autores-como-yegor-bugayenko-autor-de-elegant-objects-o-john-ousterhout-a-philosophy-of-software-design-a-este-enfoque-incremental-en-qu\xe9-contexto-la-regla-podr\xeda-ser-contraproducente",level:3},{value:"9. [Cuestionar] \xbfEst\xe1 el movimiento Clean Code en tensi\xf3n con el manifiesto Agile original? Autores como Martin Fowler y Kent Beck han se\xf1alado que el foco excesivo en &quot;c\xf3digo limpio&quot; puede llevar a &quot;over-engineering&quot;. \xbfC\xf3mo reconcili\xe1s &quot;YAGNI&quot; con &quot;Clean Code desde el d\xeda uno&quot;?",id:"9-cuestionar-est\xe1-el-movimiento-clean-code-en-tensi\xf3n-con-el-manifiesto-agile-original-autores-como-martin-fowler-y-kent-beck-han-se\xf1alado-que-el-foco-excesivo-en-c\xf3digo-limpio-puede-llevar-a-over-engineering-c\xf3mo-reconcili\xe1s-yagni-con-clean-code-desde-el-d\xeda-uno",level:3},{value:"10. [Cuestionar] La clase recomienda herramientas como SonarLint y Checkstyle. \xbfQu\xe9 argumenta Michael Feathers (&quot;Working Effectively with Legacy Code&quot;) sobre cu\xe1ndo la adopci\xf3n de herramientas de an\xe1lisis est\xe1tico puede ser CONTRAproducente en un proyecto legacy? \xbfCu\xe1l es su estrategia de &quot;code quality adoption&quot;?",id:"10-cuestionar-la-clase-recomienda-herramientas-como-sonarlint-y-checkstyle-qu\xe9-argumenta-michael-feathers-working-effectively-with-legacy-code-sobre-cu\xe1ndo-la-adopci\xf3n-de-herramientas-de-an\xe1lisis-est\xe1tico-puede-ser-contraproducente-en-un-proyecto-legacy-cu\xe1l-es-su-estrategia-de-code-quality-adoption",level:3}];function d(e){const a={h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.h3,{id:"2-investigar-qu\xe9-plantea-el-movimiento-software-craftsmanship-iniciado-por-pete-mcbreen-y-qu\xe9-cr\xedticas-ha-recibido-desde-ciertos-sectores-del-desarrollo-\xe1gil",children:'2. [Investigar] \xbfQu\xe9 plantea el movimiento "Software Craftsmanship" iniciado por Pete McBreen, y qu\xe9 cr\xedticas ha recibido desde ciertos sectores del desarrollo \xe1gil?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Pete McBreen, en su libro "Software Craftsmanship" (2001), propuso que el desarrollo de software deber\xeda tratarse como un oficio artesanal (craft) en lugar de una disciplina puramente ingenieril. El movimiento enfatiza el aprendizaje continuo a trav\xe9s de la pr\xe1ctica deliberada, el mentoring mediante apprenticeship (aprendiz \u2192 oficial \u2192 maestro), y la responsabilidad personal sobre el c\xf3digo. El manifiesto de Software Craftsmanship (2009) a\xf1ade a los valores \xe1giles: "no solo software funcionando, sino software BIEN elaborado". Las cr\xedticas principales vienen de sectores del agilismo ortodoxo que argumentan que: (a) puede fomentar elitismo ("mi c\xf3digo es m\xe1s craft que el tuyo"), (b) prioriza la excelencia t\xe9cnica sobre el valor de negocio, y (c) es un retroceso al modelo "heroico" individual que Agile intent\xf3 superar con la colaboraci\xf3n de equipo.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase menciona a Robert C. Martin pero no aborda Software Craftsmanship como movimiento. McBreen argumenta que las aplicaciones mal construidas terminan reescribi\xe9ndose, desperdiciando todo el valor de negocio. El debate contin\xfaa: en 2019, Dan North (co-creador de BDD) escribi\xf3 "The Worst Piece of Career Advice" criticando la cultura craft por alienante. Sandro Mancuso ("The Software Craftsman", 2014) defiende que la artesan\xeda y la entrega de valor no son opuestas. Comprender este debate es esencial para no adoptar Clean Code como dogma.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-la-complexity-theory-of-technical-debt-de-steve-mcconnell-y-c\xf3mo-clasifica-\xe9l-la-deuda-t\xe9cnica-de-manera-diferente-a-fowler",children:'3. [Investigar] \xbfQu\xe9 es la "Complexity Theory of Technical Debt" de Steve McConnell y c\xf3mo clasifica \xe9l la deuda t\xe9cnica de manera diferente a Fowler?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Steve McConnell, en su libro "Code Complete 2" (2004) y en diversos art\xedculos, clasific\xf3 la deuda t\xe9cnica ANTES que Fowler y de manera m\xe1s amplia, distinguiendo entre deuda de corto plazo y largo plazo. McConnell divide la deuda en: (1) Deuda intencional tomada por decisi\xf3n estrat\xe9gica (similar a Fowler), (2) Deuda no intencional por falta de skill (el equipo no sabe hacerlo mejor), (3) Deuda por "bit-rot" \u2014 el c\xf3digo se degrada con el tiempo aunque nadie lo modifique, porque el contexto cambia (nuevas versiones de frameworks, regulaciones, expectativas de usuarios). McConnell enfatiza que la deuda por bit-rot es inevitable y requiere refactorizaci\xf3n continua como pr\xe1ctica de mantenimiento, an\xe1logo al mantenimiento preventivo de infraestructura f\xedsica.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase cita a Cunningham y Fowler pero no a McConnell. "Code Complete 2" es uno de los libros m\xe1s influyentes de ingenier\xeda de software y precede por varios a\xf1os a "Clean Code". McConnell introduce la noci\xf3n de que la deuda por bit-rot es sist\xe9mica: no importa qu\xe9 tan limpio escribiste tu c\xf3digo, eventualmente necesitar\xe1 refactorizaci\xf3n porque el MUNDO cambi\xf3. Esta perspectiva complementa (y en algunos aspectos contradice) la visi\xf3n de Clean Code de que si escrib\xeds c\xf3digo limpio desde el principio, la deuda no se acumula.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"4-investigar-qu\xe9-revel\xf3-el-estudio-the-impact-of-technical-debt-on-developer-productivity-stol-et-al-2019-sobre-las-m\xe9tricas-reales-de-cu\xe1nto-tiempo-pierden-los-desarrolladores-por-deuda-t\xe9cnica",children:'4. [Investigar] \xbfQu\xe9 revel\xf3 el estudio "The Impact of Technical Debt on Developer Productivity" (Stol et al., 2019) sobre las m\xe9tricas reales de cu\xe1nto tiempo pierden los desarrolladores por deuda t\xe9cnica?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),": El estudio de Klaas-Jan Stol, Paul Ralph y colaboradores (publicado en Empirical Software Engineering, 2019) encuest\xf3 a m\xe1s de 1.400 desarrolladores profesionales y encontr\xf3 que los desarrolladores estiman perder entre el 23% y el 42% de su tiempo de trabajo lidiando con deuda t\xe9cnica, con un promedio del 30%. El estudio identific\xf3 que la deuda t\xe9cnica no solo afecta el tiempo de implementaci\xf3n sino tambi\xe9n: (a) la moral del equipo (los desarrolladores reportan frustraci\xf3n y burnout por trabajar en c\xf3digo legacy), (b) la capacidad de estimar (la incertidumbre por c\xf3digo desordenado lleva a subestimar esfuerzos), y (c) la retenci\xf3n de talento (los buenos desarrolladores tienden a irse de proyectos con alta deuda). Notablemente, el estudio encontr\xf3 que los managers subestiman consistentemente el impacto en un 40% comparado con lo que los desarrolladores reportan."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase cita que el c\xf3digo desordenado cuesta "3x m\xe1s tiempo" y "5x m\xe1s bugs", pero estas son estimaciones heur\xedsticas de Robert Martin sin respaldo de estudio espec\xedfico citado. El estudio de Stol et al. es una investigaci\xf3n emp\xedrica con metodolog\xeda rigurosa publicada en una revista revisada por pares. Proporciona evidencia concreta m\xe1s all\xe1 de las afirmaciones del libro, incluyendo el hallazgo de la brecha de percepci\xf3n manager-desarrollador \u2014que es cr\xedtico para entender por qu\xe9 la deuda t\xe9cnica persiste en las organizaciones.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-la-broken-window-theory-originada-en-criminolog\xeda-por-wilson-y-kelling-c\xf3mo-fue-espec\xedficamente-testeada-esta-teor\xeda-en-software-por-nachiappan-nagappan-microsoft-research-y-qu\xe9-resultados-cuantitativos-obtuvo",children:'5. [Conectar] La clase menciona la "Broken Window Theory" originada en criminolog\xeda por Wilson y Kelling. \xbfC\xf3mo fue espec\xedficamente testeada esta teor\xeda en software por Nachiappan Nagappan (Microsoft Research), y qu\xe9 resultados cuantitativos obtuvo?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Nachiappan Nagappan y su equipo en Microsoft Research condujeron en 2008 un estudio emp\xedrico sobre m\xfaltiples proyectos de Windows y Office midiendo la correlaci\xf3n entre "code churn" (cambios frecuentes en el mismo c\xf3digo) y densidad de bugs. Encontraron que los m\xf3dulos con alto "code churn" (los que cambian frecuentemente, t\xedpicamente c\xf3digo mal estructurado que se toca para cada feature) ten\xedan una densidad de defectos hasta 5 VECES mayor que m\xf3dulos estables. M\xe1s importante: la m\xe9trica de "organizational complexity" (cu\xe1ntos equipos tocan el mismo c\xf3digo) era un predictor a\xfan m\xe1s fuerte de defectos que la complejidad ciclom\xe1tica. Cuando c\xf3digo descuidado es tocado por m\xfaltiples equipos, la tasa de bugs se dispara \u2014confirmando emp\xedricamente la Broken Window Theory: c\xf3digo malo invita a m\xe1s c\xf3digo malo distribuido entre contribuidores.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase describe la Broken Window Theory de manera metaf\xf3rica pero no cita evidencia emp\xedrica de que funcione en software. El estudio de Nagappan (publicado en ICSE 2008, "The Influence of Organizational Structure on Software Quality") es una de las pocas validaciones cuantitativas de que la calidad se degrada en cascada. Nagappan demostr\xf3 que la m\xe9trica organizacional (cu\xe1ntos equipos tocan un archivo) es m\xe1s predictiva de bugs que las m\xe9tricas tradicionales de complejidad de c\xf3digo, lo cual da sustento cient\xedfico a la intuici\xf3n de la "ventana rota" en software.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"6-conectar-la-clase-presenta-las-4-reglas-de-dise\xf1o-simple-de-kent-beck-c\xf3mo-se-relacionan-estas-4-reglas-con-el-concepto-de-ease-vs-simplicity-que-rich-hickey-creador-de-clojure-desarroll\xf3-en-su-charla-simple-made-easy",children:'6. [Conectar] La clase presenta las 4 reglas de dise\xf1o simple de Kent Beck. \xbfC\xf3mo se relacionan estas 4 reglas con el concepto de "Ease" vs "Simplicity" que Rich Hickey (creador de Clojure) desarroll\xf3 en su charla "Simple Made Easy"?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Rich Hickey, en su charla seminal "Simple Made Easy" (Strange Loop, 2011), distingue entre "simple" (del lat\xedn "sim-plex": un solo pliegue, un solo prop\xf3sito) y "easy" (del franc\xe9s "ais\xe9": lo que est\xe1 cerca, familiar). Las 4 reglas de Beck apuntan a simplicidad genuina: "pasa los tests" (funcionalidad), "revela intenci\xf3n" (no hay enga\xf1o ni complejidad oculta), "no tiene duplicaci\xf3n" (cada concepto vive en un solo lugar), "m\xednimo n\xfamero de elementos" (no hay entrelazamientos innecesarios). Sin embargo, Hickey argumenta que los desarrolladores frecuentemente confunden "easy" (familiar, lo de siempre) con "simple" (objetivamente desacoplado). Por ejemplo: usar un ORM es "easy" (familiar para equipos Java) pero NO es "simple" porque entrelaza esquema de BD, consultas y objetos de dominio. Las reglas de Beck promueven simplicidad objetiva, no facilidad subjetiva.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase expone las 4 reglas como principios autoevidentes. La charla de Hickey (ampliamente referenciada en la comunidad) provee un marco filos\xf3fico m\xe1s profundo para entender por qu\xe9 esas reglas FUNCIONAN. Hickey argumenta que cada "entrelazamiento" (interleaving) de conceptos es la fuente de complejidad, y las reglas de Beck son precisamente formas de eliminar entrelazamientos: duplicaci\xf3n es entrelazamiento de implementaci\xf3n, intenci\xf3n poco clara es entrelazamiento de prop\xf3sito. La conexi\xf3n no est\xe1 documentada en clase.md.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"7-conectar-la-clase-menciona-que-el-70-90-del-tiempo-de-un-desarrollador-es-leyendo-c\xf3digo-citando-a-robert-c-martin-qu\xe9-metodolog\xeda-espec\xedfica-us\xf3-el-estudio-developer-reading-behavior-buse--weimer-2012-para-medir-la-legibilidad-de-c\xf3digo-y-qu\xe9-factores-resultaron-m\xe1s-predictivos-de-legibilidad-que-la-complejidad-ciclom\xe1tica",children:'7. [Conectar] La clase menciona que "el 70-90% del tiempo de un desarrollador es leyendo c\xf3digo" citando a Robert C. Martin. \xbfQu\xe9 metodolog\xeda espec\xedfica us\xf3 el estudio "Developer Reading Behavior" (Buse & Weimer, 2012) para medir la legibilidad de c\xf3digo, y qu\xe9 factores resultaron M\xc1S predictivos de legibilidad que la complejidad ciclom\xe1tica?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Raymond Buse y Westley Weimer, de la Universidad de Virginia, publicaron en 2012 "Learning a Metric for Code Readability" (IEEE TSE). Construyeron un modelo de machine learning entrenado con 120 fragmentos de c\xf3digo calificados por m\xe1s de 100 desarrolladores humanos en una escala de legibilidad de 1 a 5. Encontraron que los factores M\xc1S predictivos de baja legibilidad NO eran m\xe9tricas estructurales (complejidad ciclom\xe1tica, l\xedneas de c\xf3digo), sino: (1) n\xfamero de identificadores por l\xednea (alta densidad de variables diferentes confunde), (2) cantidad de literales sin nombre (n\xfameros m\xe1gicos y strings inline), y (3) profundidad media de anidaci\xf3n de bloques. Estos tres factores explican m\xe1s varianza en la percepci\xf3n humana de legibilidad que las m\xe9tricas tradicionales. Notablemente, el estudio encontr\xf3 que el consenso entre desarrolladores sobre qu\xe9 c\xf3digo es legible es sorprendentemente alto (correlaci\xf3n inter-evaluador de 0.72), rebatiendo la noci\xf3n de que "la legibilidad es subjetiva".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase menciona la proporci\xf3n lectura/escritura pero no cita estudios sobre QU\xc9 hace el c\xf3digo legible. El estudio de Buse & Weimer es la investigaci\xf3n m\xe1s citada sobre m\xe9tricas de legibilidad y provee evidencia emp\xedrica para varias reglas de Clean Code (nombres significativos, evitar magic numbers, funciones peque\xf1as). Sin embargo, el estudio tambi\xe9n encontr\xf3 que comentarios bien colocados MEJORAN la legibilidad percibida, matizando la postura m\xe1s extrema de Clean Code de "evita comentarios siempre que puedas".']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"8-cuestionar-la-boy-scout-rule-de-robert-c-martin-promueve-peque\xf1as-refactorizaciones-en-cada-commit-qu\xe9-objeciones-plantean-autores-como-yegor-bugayenko-autor-de-elegant-objects-o-john-ousterhout-a-philosophy-of-software-design-a-este-enfoque-incremental-en-qu\xe9-contexto-la-regla-podr\xeda-ser-contraproducente",children:'8. [Cuestionar] La "Boy Scout Rule" de Robert C. Martin promueve peque\xf1as refactorizaciones en cada commit. \xbfQu\xe9 objeciones plantean autores como Yegor Bugayenko (autor de "Elegant Objects") o John Ousterhout ("A Philosophy of Software Design") a este enfoque incremental? \xbfEn qu\xe9 contexto la regla podr\xeda ser contraproducente?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Yegor Bugayenko argumenta en "Elegant Objects" (2017) que las micro-refactorizaciones sin un objetivo de dise\xf1o claro pueden empeorar el c\xf3digo a largo plazo porque cada mejora local puede aumentar la inconsistencia global del dise\xf1o. Si cada desarrollador aplica "su versi\xf3n" de Boy Scout Rule sin una arquitectura acordada, el resultado es un collage de estilos inconsistentes. John Ousterhout, en "A Philosophy of Software Design" (2018), critica directamente el incrementalismo de Clean Code argumentando que el problema no son las funciones largas sino la PROFUNDIDAD de las abstracciones: una clase con 400 l\xedneas que encapsula una abstracci\xf3n profunda es BETTER que 20 clases de 20 l\xedneas que provocan "shallow modules" (m\xf3dulos superficiales cuya interfaz es casi tan compleja como su implementaci\xf3n). Ousterhout defiende que lo importante es dise\xf1ar interfaces que oculten complejidad, no minimizar l\xedneas por funci\xf3n. Contraproducente cuando: (a) el equipo rota frecuentemente y cada dev aplica est\xe1ndares distintos, (b) el c\xf3digo base no tiene tests (refactorizar sin red de seguridad es peligroso), (c) la refactorizaci\xf3n agrega capas de abstracci\xf3n sin valor real.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase presenta la Boy Scout Rule como un bien incuestionable. Sin embargo, existe debate real en la comunidad sobre el incrementalismo sin direcci\xf3n. Ousterhout ense\xf1a en Stanford y su libro es usado en universidades. Bugayenko es un cr\xedtico vocal de Clean Code desde la perspectiva de OOP ortodoxo. Un desarrollador con criterio debe entender CU\xc1NDO aplicar la Boy Scout Rule (c\xf3digo con tests, dise\xf1o estable) y cu\xe1ndo no (c\xf3digo legacy sin tests, antes de una gran reestructuraci\xf3n planeada). La pregunta fuerza al alumno a buscar m\xe1s all\xe1 del libro."]}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"9-cuestionar-est\xe1-el-movimiento-clean-code-en-tensi\xf3n-con-el-manifiesto-agile-original-autores-como-martin-fowler-y-kent-beck-han-se\xf1alado-que-el-foco-excesivo-en-c\xf3digo-limpio-puede-llevar-a-over-engineering-c\xf3mo-reconcili\xe1s-yagni-con-clean-code-desde-el-d\xeda-uno",children:'9. [Cuestionar] \xbfEst\xe1 el movimiento Clean Code en tensi\xf3n con el manifiesto Agile original? Autores como Martin Fowler y Kent Beck han se\xf1alado que el foco excesivo en "c\xf3digo limpio" puede llevar a "over-engineering". \xbfC\xf3mo reconcili\xe1s "YAGNI" con "Clean Code desde el d\xeda uno"?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Existe una tensi\xf3n real entre YAGNI ("You Ain\'t Gonna Need It") y Clean Code temprano. YAGNI dice que no construyas abstracciones para requisitos futuros que quiz\xe1s nunca lleguen; Clean Code parece pedir que el c\xf3digo est\xe9 bien dise\xf1ado DESDE EL PRINCIPIO. La reconciliaci\xf3n viene de entender que Clean Code no pide "dise\xf1o para el futuro" sino "dise\xf1o que NO OBSTRUYA el futuro". Un c\xf3digo limpio con nombres claros, funciones peque\xf1as y sin duplicaci\xf3n es m\xe1s F\xc1CIL de extender, no est\xe1 m\xe1s PREPARADO para un caso espec\xedfico. Martin Fowler distingue entre "refactoring preparatorio" (malo: construir flexibilidad que no necesit\xe1s) y "refactoring oportun\xedstico" (bueno: limpiar lo que ya existe). Kent Beck, coautor del manifiesto \xe1gil y padre de XP, defiende que las reglas de simplicidad (incluyendo "m\xednimo n\xfamero de elementos") son el contrapeso natural: Clean Code que acumula abstracciones innecesarias NO es limpio. La clave es: hac\xe9 tu c\xf3digo legible y simple AHORA para lo que hace AHORA; no agregues patrones "por si acaso".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta Clean Code como complementario a Agile sin explorar la tensi\xf3n. En la pr\xe1ctica, equipos que adoptan Clean Code dogm\xe1ticamente tienden a sobre-ingenierizar temprano, violando YAGNI. El art\xedculo "Is High Quality Software Worth the Cost?" de Martin Fowler (2019, martinfowler.com) aborda esta tensi\xf3n directamente, argumentando que la calidad interna NO es un trade-off contra velocidad \u2014el c\xf3digo limpio bien entendido ACELERA el desarrollo porque reduce la fricci\xf3n de cambio. Pero advierte que "calidad" malinterpretada como "arquitectura flexible para escenarios hipot\xe9ticos" S\xcd es perjudicial.']}),"\n",(0,n.jsx)(a.hr,{}),"\n",(0,n.jsx)(a.h3,{id:"10-cuestionar-la-clase-recomienda-herramientas-como-sonarlint-y-checkstyle-qu\xe9-argumenta-michael-feathers-working-effectively-with-legacy-code-sobre-cu\xe1ndo-la-adopci\xf3n-de-herramientas-de-an\xe1lisis-est\xe1tico-puede-ser-contraproducente-en-un-proyecto-legacy-cu\xe1l-es-su-estrategia-de-code-quality-adoption",children:'10. [Cuestionar] La clase recomienda herramientas como SonarLint y Checkstyle. \xbfQu\xe9 argumenta Michael Feathers ("Working Effectively with Legacy Code") sobre cu\xe1ndo la adopci\xf3n de herramientas de an\xe1lisis est\xe1tico puede ser CONTRAproducente en un proyecto legacy? \xbfCu\xe1l es su estrategia de "code quality adoption"?'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Respuesta"}),': Michael Feathers, en "Working Effectively with Legacy Code" (2004), argumenta que imponer herramientas de an\xe1lisis est\xe1tico con reglas estrictas en un proyecto legacy MASIVO puede ser contraproducente por tres razones: (1) "Alert fatigue": si corr\xe9s SonarQube en un proyecto legacy de 500K l\xedneas y obten\xe9s 15,000 warnings, el equipo los ignora TODOS \u2014incluidos los genuinamente peligrosos\u2014, (2) Las correcciones masivas sin tests generan regresiones: arreglar 2,000 violaciones de Checkstyle sin cobertura de tests es dispararse en el pie, (3) El costo pol\xedtico: los desarrolladores asocian la herramienta con dolor y burocracia, rechazando futuras iniciativas de calidad. La estrategia de Feathers es: introducir herramientas de an\xe1lisis de forma GRADUAL, m\xf3dulo por m\xf3dulo, empezando por los m\xf3dulos que M\xc1S se modifican (los que m\xe1s "duelen"), usando la regla de "no empeorar" (el warning count no debe subir) antes de "llegar a cero".']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase recomienda herramientas sin el contexto de adopci\xf3n. Feathers es la autoridad en legacy code y su libro es el complemento pr\xe1ctico indispensable a Clean Code. Su advertencia no est\xe1 en Clean Code porque el libro de Martin asume que empez\xe1s un proyecto limpio o que pod\xe9s refactorizar todo. En la realidad corporativa donde el curso aplica (proyecto legacy de n\xf3minas), el enfoque de Feathers es m\xe1s pragm\xe1tico y los alumnos deben conocerlo para no aplicar herramientas de manera ingenua."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>s,x:()=>t});var i=o(96540);const n={},r=i.createContext(n);function s(e){const a=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),i.createElement(r.Provider,{value:a},e.children)}}}]);